# 13-nov-2026 · Around Mamboro (north coast of Central Sumba), where Eco Beach City is.
# Sources: Dinas Pariwisata Sumba Tengah (pariwisatasumtengsite.wordpress.com, "Pesona Bahari/Pantai"),
# Pos-Kupang 22-feb-2025 (Kapulit), tripsumba.com (Lenang), Tempo English 2024 (Deri Kambajawa),
# backindo.com + javaisbeautiful.com (Kolam Jodoh), molon.de (Karendi photos), OpenStreetMap / Nominatim.
# Coordinates: OSM. Where OSM has no beach point, the village centre is used (marked "village").
# Rules: real places only, no hotels in listings, no invented facts. Photos are stock photos of the same
# kind of place (fp=1, labelled as such on the page) until real photos of each spot exist.
from gallery import GALLERY

def _p(s, c, r, ll, sec, n_id, tr):
    d = {"s": s, "c": c, "sec": sec, "r": r, "ll": ll, "img": None, "n": {"id": n_id}}
    d.update(tr)
    return d

MAMBORO = [
 _p("kapulit-beach", "beach", "st", [-9.37861, 119.58439], True, "Pantai Kapulit", {  # village Watu Asa
  "en": {"n": "Kapulit Beach", "t": "A wide white-sand beach at Watu Asa, in Mamboro on the north coast of Central Sumba, about 34 km from Waibakul. The waves are usually gentle, coral formations along the shore give some shade, and a paved road leads there. Locals come to fish and snorkel.", "tip": "Bring water and snorkel gear: there are no shops on the beach."},
  "es": {"n": "Playa de Kapulit", "t": "Una amplia playa de arena blanca en Watu Asa, en Mamboro, en la costa norte de Sumba Central, a unos 34 km de Waibakul. Las olas suelen ser suaves, las formaciones de coral de la orilla dan algo de sombra y se llega por carretera asfaltada. La gente de la zona viene a pescar y a hacer esnórquel.", "tip": "Lleva agua y equipo de esnórquel: en la playa no hay tiendas."},
  "id": {"n": "Pantai Kapulit", "t": "Pantai berpasir putih yang luas di Desa Watu Asa, Kecamatan Mamboro, pesisir utara Sumba Tengah, sekitar 34 km dari Waibakul. Ombaknya biasanya tenang, batu karang di tepi pantai memberi sedikit keteduhan, dan jalannya sudah beraspal. Warga datang untuk memancing dan snorkeling.", "tip": "Bawa air minum dan alat snorkeling: tidak ada warung di pantai."},
  "de": {"n": "Kapulit-Strand", "t": "Ein breiter weißer Sandstrand in Watu Asa, im Bezirk Mamboro an der Nordküste Zentral-Sumbas, etwa 34 km von Waibakul. Die Wellen sind meist sanft, Korallenformationen am Ufer spenden etwas Schatten, und eine asphaltierte Straße führt hin. Einheimische kommen zum Angeln und Schnorcheln.", "tip": "Wasser und Schnorchelausrüstung mitbringen: Am Strand gibt es keine Läden."},
  "fr": {"n": "Plage de Kapulit", "t": "Une large plage de sable blanc à Watu Asa, dans le district de Mamboro, sur la côte nord du centre de Sumba, à environ 34 km de Waibakul. Les vagues sont en général douces, les formations coralliennes du rivage offrent un peu d'ombre et une route goudronnée y mène. Les habitants y viennent pêcher et faire du snorkeling.", "tip": "Apportez de l'eau et votre matériel de snorkeling : il n'y a aucune boutique sur la plage."},
  "nl": {"n": "Kapulit-strand", "t": "Een breed wit zandstrand in Watu Asa, in Mamboro aan de noordkust van Midden-Sumba, zo'n 34 km van Waibakul. De golven zijn meestal rustig, koraalformaties langs de kust geven wat schaduw en er loopt een geasfalteerde weg naartoe. Bewoners komen er vissen en snorkelen.", "tip": "Neem water en snorkelspullen mee: er zijn geen winkels op het strand."}}),
 _p("mananga-beach", "beach", "st", [-9.37817, 119.53747], True, "Pantai Mananga", {  # village Wendewa Utara
  "en": {"n": "Mananga Beach", "t": "A long beach at Mananga, in Mamboro, reached by crossing a small saltwater lagoon in a local boat. Mamboro's fishermen pull up their boats here, so you can buy fish straight from the catch.", "tip": "Agree the boat fare before you cross the lagoon, and bring cash for fresh fish."},
  "es": {"n": "Playa de Mananga", "t": "Una playa larga en Mananga, en Mamboro, a la que se llega cruzando en barca una pequeña laguna de agua salada. Aquí varan sus barcas los pescadores de Mamboro, así que puedes comprar el pescado recién sacado del mar.", "tip": "Acuerda el precio de la barca antes de cruzar la laguna y lleva efectivo para el pescado."},
  "id": {"n": "Pantai Mananga", "t": "Pantai panjang di Mananga, Kecamatan Mamboro, yang dicapai dengan menyeberangi danau kecil air asin naik perahu warga. Di sinilah nelayan Mamboro menambatkan perahu, jadi Anda bisa membeli ikan segar langsung dari hasil tangkapan.", "tip": "Sepakati ongkos perahu sebelum menyeberang, dan bawa uang tunai untuk membeli ikan."},
  "de": {"n": "Mananga-Strand", "t": "Ein langer Strand in Mananga im Bezirk Mamboro, den man erreicht, indem man mit einem einheimischen Boot eine kleine Salzwasserlagune überquert. Hier ziehen die Fischer von Mamboro ihre Boote an Land, und man kann Fisch direkt vom Fang kaufen.", "tip": "Den Bootspreis vor der Überfahrt vereinbaren und Bargeld für frischen Fisch mitnehmen."},
  "fr": {"n": "Plage de Mananga", "t": "Une longue plage à Mananga, dans le district de Mamboro, que l'on rejoint en traversant une petite lagune d'eau salée en barque. Les pêcheurs de Mamboro y tirent leurs bateaux sur le sable : on peut acheter le poisson tout juste pêché.", "tip": "Fixez le prix de la barque avant la traversée et prévoyez des espèces pour le poisson."},
  "nl": {"n": "Mananga-strand", "t": "Een lang strand bij Mananga, in Mamboro, dat je bereikt door met een lokale boot een kleine zoutwaterlagune over te steken. De vissers van Mamboro trekken hier hun boten op het strand, dus je koopt vis direct van de vangst.", "tip": "Spreek de prijs van de boot af voor je de lagune oversteekt en neem contant geld mee voor verse vis."}}),
 _p("karendi-beach", "beach", "st", [-9.40727, 119.44141], True, "Pantai Karendi", {  # village Susu Wendewa
  "en": {"n": "Karendi Beach", "t": "A white-sand beach at Susu Wendewa, in western Mamboro, where two river mouths meet the sea under casuarina trees. Japanese cannons from the Second World War stand on a stone monument by the shore, and villagers collect seafood off the beach.", "tip": "The salty river on the way has crocodiles: stay on the track and keep out of the water there."},
  "es": {"n": "Playa de Karendi", "t": "Una playa de arena blanca en Susu Wendewa, en el oeste de Mamboro, donde dos desembocaduras de río se juntan con el mar bajo las casuarinas. Junto a la orilla hay cañones japoneses de la Segunda Guerra Mundial sobre un monumento de piedra, y la gente del pueblo marisquea en la playa.", "tip": "En el río salado del camino hay cocodrilos: no te salgas del sendero ni te metas en el agua allí."},
  "id": {"n": "Pantai Karendi", "t": "Pantai berpasir putih di Desa Susu Wendewa, bagian barat Mamboro, tempat dua muara sungai bertemu laut di bawah pohon cemara laut. Di tepi pantai ada meriam Jepang dari Perang Dunia II di atas tugu batu, dan warga mencari hasil laut di pantai.", "tip": "Sungai air asin di perjalanan dihuni buaya: tetap di jalur dan jangan masuk ke air di sana."},
  "de": {"n": "Karendi-Strand", "t": "Ein weißer Sandstrand in Susu Wendewa im Westen von Mamboro, wo zwei Flussmündungen unter Kasuarinen ins Meer fließen. Am Ufer stehen japanische Kanonen aus dem Zweiten Weltkrieg auf einem Steindenkmal, und Dorfbewohner sammeln Meeresfrüchte am Strand.", "tip": "Im salzigen Fluss auf dem Weg leben Krokodile: auf dem Pfad bleiben und dort nicht ins Wasser gehen."},
  "fr": {"n": "Plage de Karendi", "t": "Une plage de sable blanc à Susu Wendewa, dans l'ouest du district de Mamboro, où deux embouchures de rivière rejoignent la mer sous les filaos. Des canons japonais de la Seconde Guerre mondiale reposent sur un monument en pierre près du rivage, et les villageois ramassent des fruits de mer sur la plage.", "tip": "La rivière salée sur le trajet abrite des crocodiles : restez sur le chemin et n'entrez pas dans l'eau à cet endroit."},
  "nl": {"n": "Karendi-strand", "t": "Een wit zandstrand bij Susu Wendewa, in het westen van Mamboro, waar twee riviermondingen onder casuarinabomen in zee uitkomen. Bij de kust staan Japanse kanonnen uit de Tweede Wereldoorlog op een stenen monument, en dorpelingen zoeken er zeevruchten.", "tip": "In de zoute rivier onderweg leven krokodillen: blijf op het pad en ga daar niet het water in."}}),
 _p("lenang-beach", "beach", "st", [-9.39921, 119.75263], True, "Pantai Pahar, Lenang", {  # village Lenang
  "en": {"n": "Lenang Beach (Pahar)", "t": "Pahar Beach at Lenang, in Umbu Ratu Nggay, is a stretch of white sand with clear blue-green water, mangroves and coconut palms, about 40 km from Waibakul. The sea is usually calm enough to swim and snorkel, and villagers still make salt the traditional way.", "tip": "Ask in the village if you can watch the salt-making. Bring shade and water: facilities are basic."},
  "es": {"n": "Playa de Lenang (Pahar)", "t": "La playa de Pahar, en Lenang (Umbu Ratu Nggay), es una franja de arena blanca con agua clara verde azulada, manglares y cocoteros, a unos 40 km de Waibakul. El mar suele estar lo bastante tranquilo para nadar y hacer esnórquel, y en el pueblo todavía se hace sal de forma tradicional.", "tip": "Pregunta en el pueblo si puedes ver cómo hacen la sal. Lleva sombra y agua: los servicios son básicos."},
  "id": {"n": "Pantai Pahar, Lenang", "t": "Pantai Pahar di Desa Lenang, Kecamatan Umbu Ratu Nggay, adalah hamparan pasir putih dengan air toska yang jernih, bakau dan pohon kelapa, sekitar 40 km dari Waibakul. Lautnya biasanya cukup tenang untuk berenang dan snorkeling, dan warga masih membuat garam secara tradisional.", "tip": "Tanyakan ke warga apakah Anda boleh melihat pembuatan garam. Bawa peneduh dan air: fasilitas masih sederhana."},
  "de": {"n": "Lenang-Strand (Pahar)", "t": "Der Pahar-Strand bei Lenang in Umbu Ratu Nggay ist ein weißer Sandstreifen mit klarem, blaugrünem Wasser, Mangroven und Kokospalmen, etwa 40 km von Waibakul. Das Meer ist meist ruhig genug zum Schwimmen und Schnorcheln, und im Dorf wird noch auf traditionelle Weise Salz gewonnen.", "tip": "Im Dorf fragen, ob man bei der Salzgewinnung zusehen darf. Schatten und Wasser mitbringen: Es gibt nur das Nötigste."},
  "fr": {"n": "Plage de Lenang (Pahar)", "t": "La plage de Pahar, à Lenang (Umbu Ratu Nggay), est une bande de sable blanc à l'eau claire et turquoise, bordée de mangroves et de cocotiers, à environ 40 km de Waibakul. La mer est en général assez calme pour nager et faire du snorkeling, et les villageois produisent encore le sel de façon traditionnelle.", "tip": "Demandez au village si vous pouvez assister à la fabrication du sel. Prévoyez de l'ombre et de l'eau : les équipements sont sommaires."},
  "nl": {"n": "Lenang-strand (Pahar)", "t": "Het Pahar-strand bij Lenang, in Umbu Ratu Nggay, is een strook wit zand met helder blauwgroen water, mangroven en kokospalmen, zo'n 40 km van Waibakul. De zee is meestal rustig genoeg om te zwemmen en te snorkelen, en in het dorp wordt nog op traditionele wijze zout gemaakt.", "tip": "Vraag in het dorp of je mag kijken bij het zoutmaken. Neem schaduw en water mee: de voorzieningen zijn eenvoudig."}}),
 _p("deri-kambajawa", "village", "st", [-9.61756, 119.64548], True, "Kampung Adat Deri Kambajawa", {  # village Umbu Pabal
  "en": {"n": "Deri Kambajawa Village", "t": "A traditional village in the Umbu Pabal customary area, east of Waibakul, known for its tower-like clan houses that reach up to about 30 metres, among the tallest in Sumba. It is remote and not set up for tourism.", "tip": "Go only with a local guide who can introduce you, and follow village customs: guestbook, a small donation, ask before photos."},
  "es": {"n": "Aldea de Deri Kambajawa", "t": "Una aldea tradicional en el territorio consuetudinario de Umbu Pabal, al este de Waibakul, conocida por sus casas de clan en forma de torre, de hasta unos 30 metros, de las más altas de Sumba. Es remota y no está preparada para el turismo.", "tip": "Ve solo con un guía local que te presente y respeta las costumbres: libro de visitas, un pequeño donativo y pedir permiso para las fotos."},
  "id": {"n": "Kampung Adat Deri Kambajawa", "t": "Kampung adat di wilayah adat Umbu Pabal, sebelah timur Waibakul, terkenal dengan rumah suku berbentuk menara yang tingginya bisa mencapai sekitar 30 meter, termasuk yang tertinggi di Sumba. Lokasinya terpencil dan belum disiapkan untuk wisata.", "tip": "Datang hanya bersama pemandu lokal yang bisa memperkenalkan Anda, dan ikuti adat: buku tamu, sumbangan kecil, minta izin sebelum memotret."},
  "de": {"n": "Dorf Deri Kambajawa", "t": "Ein traditionelles Dorf im Gewohnheitsrechtsgebiet Umbu Pabal östlich von Waibakul, bekannt für seine turmartigen Clanhäuser mit bis zu etwa 30 Metern Höhe, die zu den höchsten Sumbas zählen. Es liegt abgelegen und ist nicht auf Tourismus eingestellt.", "tip": "Nur mit einem lokalen Guide hingehen, der Sie vorstellt, und die Dorfregeln beachten: Gästebuch, kleine Spende, vor Fotos fragen."},
  "fr": {"n": "Village de Deri Kambajawa", "t": "Un village traditionnel du territoire coutumier d'Umbu Pabal, à l'est de Waibakul, connu pour ses maisons claniques en forme de tour qui atteignent environ 30 mètres, parmi les plus hautes de Sumba. Il est isolé et n'est pas aménagé pour le tourisme.", "tip": "N'y allez qu'avec un guide local qui vous présentera, et respectez les usages : livre d'or, petit don, demander avant de photographier."},
  "nl": {"n": "Dorp Deri Kambajawa", "t": "Een traditioneel dorp in het adatgebied Umbu Pabal, ten oosten van Waibakul, bekend om zijn torenachtige clanhuizen van tot zo'n 30 meter hoog, bij de hoogste van Sumba. Het ligt afgelegen en is niet ingericht op toerisme.", "tip": "Ga alleen met een lokale gids die je kan voorstellen en volg de gebruiken: gastenboek, een kleine donatie, vraag voor je fotografeert."}}),
 _p("maloba-beach", "beach", "st", [-9.76294, 119.61802], False, "Pantai Maloba", {
  "en": {"n": "Maloba Beach", "t": "A wide white-sand beach on the south coast of Central Sumba, about 25 km south of Waibakul. The sand is firm enough to walk easily, and a coral outcrop holds the grave of Appu Ladu, said to be the first settler. Neighbouring Aili Beach has coral rocks along the shore.", "tip": "Waves on the south coast change quickly: ask locally before swimming. Treat the grave as a sacred site and do not climb on it."},
  "es": {"n": "Playa de Maloba", "t": "Una amplia playa de arena blanca en la costa sur de Sumba Central, a unos 25 km al sur de Waibakul. La arena es tan firme que se camina con facilidad, y sobre una roca de coral está la tumba de Appu Ladu, que según la tradición fue el primer poblador. La vecina playa de Aili tiene rocas de coral en la orilla.", "tip": "Las olas de la costa sur cambian rápido: pregunta allí antes de bañarte. La tumba es un lugar sagrado: no te subas a ella."},
  "id": {"n": "Pantai Maloba", "t": "Pantai berpasir putih yang luas di pesisir selatan Sumba Tengah, sekitar 25 km di selatan Waibakul. Pasirnya padat sehingga mudah dijelajahi, dan di atas batu karang terdapat makam Appu Ladu yang disebut sebagai pemukim pertama. Pantai Aili di sebelahnya memiliki batu karang di sepanjang tepi.", "tip": "Ombak di pantai selatan cepat berubah: tanyakan ke warga sebelum berenang. Hormati makam sebagai tempat sakral dan jangan memanjatnya."},
  "de": {"n": "Maloba-Strand", "t": "Ein breiter weißer Sandstrand an der Südküste Zentral-Sumbas, etwa 25 km südlich von Waibakul. Der Sand ist so fest, dass man bequem darauf gehen kann, und auf einem Korallenfelsen liegt das Grab von Appu Ladu, der als erster Siedler gilt. Der benachbarte Aili-Strand hat Korallenfelsen am Ufer.", "tip": "Die Wellen an der Südküste ändern sich schnell: vor dem Baden vor Ort fragen. Das Grab ist ein heiliger Ort, nicht darauf klettern."},
  "fr": {"n": "Plage de Maloba", "t": "Une large plage de sable blanc sur la côte sud du centre de Sumba, à environ 25 km au sud de Waibakul. Le sable est assez ferme pour y marcher facilement, et un rocher corallien abrite la tombe d'Appu Ladu, considéré comme le premier habitant. La plage voisine d'Aili est bordée de rochers coralliens.", "tip": "Sur la côte sud, les vagues changent vite : renseignez-vous sur place avant de vous baigner. La tombe est un lieu sacré, n'y grimpez pas."},
  "nl": {"n": "Maloba-strand", "t": "Een breed wit zandstrand aan de zuidkust van Midden-Sumba, zo'n 25 km ten zuiden van Waibakul. Het zand is stevig genoeg om makkelijk te lopen, en op een koraalrots ligt het graf van Appu Ladu, die als eerste bewoner geldt. Het naburige Aili-strand heeft koraalrotsen langs de kust.", "tip": "De golven aan de zuidkust veranderen snel: vraag ter plekke voor je gaat zwemmen. Het graf is heilig, klim er niet op."}}),
 _p("konda-beach", "beach", "st", [-9.7765, 119.6640], True, "Pantai Konda", {  # near the Konda river mouth (OSM)
  "en": {"n": "Konda Beach", "t": "A black-sand beach near the mouth of the Konda river on the south coast of Central Sumba, rare on an island of white beaches. Fishermen work here, surfers come for the waves and the islet of Pulau Konda sits just offshore.", "tip": "Combine it with Maloba, about 5 km west. Swim only on calm days."},
  "es": {"n": "Playa de Konda", "t": "Una playa de arena negra junto a la desembocadura del río Konda, en la costa sur de Sumba Central, algo poco común en una isla de playas blancas. Aquí faenan pescadores, vienen surfistas por las olas y justo enfrente está el islote de Pulau Konda.", "tip": "Combínala con Maloba, unos 5 km al oeste. Báñate solo los días de calma."},
  "id": {"n": "Pantai Konda", "t": "Pantai berpasir hitam di dekat muara Sungai Konda, pesisir selatan Sumba Tengah, langka di pulau yang penuh pantai pasir putih. Nelayan bekerja di sini, peselancar datang untuk ombaknya, dan Pulau Konda yang kecil berada tepat di lepas pantai.", "tip": "Gabungkan dengan Pantai Maloba, sekitar 5 km di sebelah barat. Berenang hanya saat laut tenang."},
  "de": {"n": "Konda-Strand", "t": "Ein schwarzer Sandstrand nahe der Mündung des Konda-Flusses an der Südküste Zentral-Sumbas, selten auf einer Insel der weißen Strände. Hier arbeiten Fischer, Surfer kommen wegen der Wellen, und direkt vor der Küste liegt das Inselchen Pulau Konda.", "tip": "Mit Maloba verbinden, etwa 5 km westlich. Nur bei ruhiger See baden."},
  "fr": {"n": "Plage de Konda", "t": "Une plage de sable noir près de l'embouchure de la rivière Konda, sur la côte sud du centre de Sumba, chose rare sur une île aux plages blanches. Les pêcheurs y travaillent, les surfeurs viennent pour les vagues et l'îlot de Pulau Konda se trouve juste au large.", "tip": "À combiner avec Maloba, à environ 5 km à l'ouest. Baignade seulement par mer calme."},
  "nl": {"n": "Konda-strand", "t": "Een zwart zandstrand bij de monding van de Konda-rivier aan de zuidkust van Midden-Sumba, zeldzaam op een eiland vol witte stranden. Hier werken vissers, surfers komen voor de golven en vlak voor de kust ligt het eilandje Pulau Konda.", "tip": "Combineer met Maloba, zo'n 5 km naar het westen. Zwem alleen bij kalme zee."}}),
 _p("kolam-jodoh-waterfall", "waterfall", "stim", [-9.81055, 119.78883], False, "Air Terjun Kolam Jodoh", {
  "en": {"n": "Kolam Jodoh Waterfall", "t": "A small multi-step waterfall that pours into a clear natural pool ringed by greenery, at Umamanu in Lewa Tidahu, just across the border in East Sumba. Locals call it Pandjilu Watu, the water jar, and legend says couples who visit together get their wishes, hence the name Lovers' Pool. A short walk through farmland leads there from the road.", "tip": "Bring a towel for a swim and sandals with grip for the wet rocks."},
  "es": {"n": "Cascada de Kolam Jodoh", "t": "Una pequeña cascada escalonada que cae en una poza natural de agua clara rodeada de vegetación, en Umamanu (Lewa Tidahu), justo al otro lado del límite con Sumba Oriental. La gente la llama Pandjilu Watu, la tinaja de agua, y la leyenda dice que las parejas que la visitan juntas ven cumplidos sus deseos: de ahí el nombre de Poza de los Enamorados. Se llega con un paseo corto entre campos desde la carretera.", "tip": "Lleva toalla para bañarte y sandalias que agarren bien en las rocas mojadas."},
  "id": {"n": "Air Terjun Kolam Jodoh", "t": "Air terjun bertingkat kecil yang jatuh ke kolam alami berair jernih dikelilingi tanaman hijau, di Desa Umamanu, Kecamatan Lewa Tidahu, tepat di seberang batas Sumba Timur. Warga menyebutnya Pandjilu Watu, tempayan air, dan legenda mengatakan pasangan yang datang bersama akan terkabul keinginannya, karena itu dinamai Kolam Jodoh. Dari jalan cukup berjalan sebentar melewati ladang.", "tip": "Bawa handuk untuk berenang dan sandal yang tidak licin untuk bebatuan basah."},
  "de": {"n": "Kolam-Jodoh-Wasserfall", "t": "Ein kleiner, gestufter Wasserfall, der in ein klares Naturbecken inmitten von Grün fällt, in Umamanu (Lewa Tidahu), knapp jenseits der Grenze in Ost-Sumba. Einheimische nennen ihn Pandjilu Watu, den Wasserkrug, und der Legende nach gehen Paaren, die ihn gemeinsam besuchen, ihre Wünsche in Erfüllung, daher der Name Becken der Verliebten. Von der Straße führt ein kurzer Weg durch Felder hin.", "tip": "Ein Handtuch zum Baden und rutschfeste Sandalen für die nassen Felsen mitnehmen."},
  "fr": {"n": "Cascade de Kolam Jodoh", "t": "Une petite cascade en gradins qui se jette dans un bassin naturel limpide entouré de verdure, à Umamanu (Lewa Tidahu), juste de l'autre côté de la limite avec l'est de Sumba. Les habitants l'appellent Pandjilu Watu, la jarre d'eau, et la légende dit que les couples qui la visitent ensemble voient leurs vœux exaucés, d'où son nom de Bassin des amoureux. On y accède depuis la route par une courte marche à travers les champs.", "tip": "Prévoyez une serviette pour vous baigner et des sandales qui accrochent sur les rochers mouillés."},
  "nl": {"n": "Kolam Jodoh-waterval", "t": "Een kleine getrapte waterval die in een helder natuurlijk bassin tussen het groen valt, bij Umamanu in Lewa Tidahu, net over de grens in Oost-Sumba. De bewoners noemen hem Pandjilu Watu, de waterkruik, en volgens de legende komen de wensen uit van stellen die hem samen bezoeken, vandaar de naam Poel van de Geliefden. Vanaf de weg loop je er in korte tijd door de akkers naartoe.", "tip": "Neem een handdoek mee om te zwemmen en sandalen met grip voor de natte rotsen."}}),
]

